import { test } from "node:test";
import assert from "node:assert/strict";
import { readFileSync } from "node:fs";
import * as conv from "../runtime/conv.ts";
import * as tt from "./term_typographer.ts";
import { load } from "./testhelpers.ts";

// Vectors are generated by ts/tools/gen-render-vectors from Go's real render package (build tag javascript).
interface Pair {
  in: string;
  out: string | null;
}
interface Custom {
  terms: [string, string][];
  in: string;
  out: string | null;
}
interface Vectors {
  terms: [string, string][];
  isNotTerm: number[];
  fixTermTypo: Pair[];
  fixTermTypoCustom: Custom[];
}
const data: Vectors = JSON.parse(readFileSync(new URL("./testdata/render_vectors.json", import.meta.url), "utf8"));
const loaded = await load();

test("NewTerms has every entry of the Go dictionary", () => {
  const terms = tt.NewTerms();
  assert.equal(terms.size, data.terms.length);
  for (const [k, v] of data.terms) {
    assert.equal(terms.get(k), v, "term " + k);
  }
  // a copy: changing it does not change the next one
  terms.set("flutter", "x");
  assert.equal(tt.NewTerms().get("flutter"), "Flutter");
});

test("isNotTerm matches Go for every byte", () => {
  for (let i = 0; i < 256; i++) {
    assert.equal(tt.isNotTerm(i) ? 1 : 0, data.isNotTerm[i], "byte " + i);
  }
});

test("FixTermTypo matches Go", { skip: loaded.skip }, () => {
  const render = loaded.render!;
  const parse = loaded.parse!;
  assert.ok(data.fixTermTypo.length >= 300);
  const r = render.NewBaseRenderer(new parse.Tree(), render.NewOptions(), parse.NewOptions());
  for (const v of data.fixTermTypo) {
    const out = conv.StringFromBytes(r.FixTermTypo(conv.BytesFromString(v.in)));
    assert.equal(out, v.out, "input " + JSON.stringify(v.in));
  }
});

test("FixTermTypo with user terms matches Go, including the Go panic for a shorter replacement", { skip: loaded.skip }, () => {
  const render = loaded.render!;
  const parse = loaded.parse!;
  for (const v of data.fixTermTypoCustom) {
    const o = render.NewOptions();
    o.Terms = new Map<string, string>(v.terms);
    const r = render.NewBaseRenderer(new parse.Tree(), o, parse.NewOptions());
    if (null === v.out) {
      assert.throws(() => r.FixTermTypo(conv.BytesFromString(v.in)), "input " + JSON.stringify(v.in));
    } else {
      // Go writes bytes of the replacement into the token bytes, which can leave invalid UTF-8; the JSON of Go has a U+FFFD for each such byte, as conv.StringFromBytes does
      const out = conv.StringFromBytes(r.FixTermTypo(conv.BytesFromString(v.in)));
      assert.equal(out, v.out, "input " + JSON.stringify(v.in));
    }
  }
});
